package com.braseiro.dnd5e;
import org.json.JSONArray;import org.json.JSONObject;
/** Persistent faction-to-faction relations, treaties, wars and timed obligations. */
public final class FactionDiplomacyEngine {
 private FactionDiplomacyEngine(){}
 public static JSONObject apply(JSONObject state,JSONObject event,int day){JSONObject o=copy(state);try{String other=event==null?"":event.optString("other_faction").trim();if(other.length()==0)return o;JSONObject rel=obj(o,"relations");JSONObject r=obj(rel,other);r.put("score",Math.max(-100,Math.min(100,r.optInt("score",0)+event.optInt("relation_delta",0)))).put("last_day",Math.max(1,day));String status=event.optString("status").trim();if(status.length()>0)r.put("status",status);rel.put(other,r);o.put("relations",rel);String treaty=event.optString("treaty").trim();if(treaty.length()>0)addUnique(o,"treaties",new JSONObject().put("key",event.optString("key",other+":"+treaty)).put("with",other).put("terms",treaty).put("start_day",day).put("expires_day",event.optInt("expires_day",Integer.MAX_VALUE)).put("status","active"));String war=event.optString("war_goal").trim();if(war.length()>0)addUnique(o,"wars",new JSONObject().put("key",event.optString("key","war:"+other)).put("against",other).put("goal",war).put("start_day",day).put("status","active"));}catch(Exception ignored){}return o;}
 public static JSONObject advanceDay(JSONObject state,int day){JSONObject o=copy(state);try{JSONArray a=arr(o,"treaties");for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x==null)continue;if("active".equals(x.optString("status"))&&x.optInt("expires_day",Integer.MAX_VALUE)<=day)x.put("status","expired").put("expired_day",Math.max(1,day)).put("consequence_pending",true);}o.put("treaties",a).put("current_day",Math.max(1,day));}catch(Exception ignored){}return o;}
 public static JSONObject acknowledgeTreatyExpiry(JSONObject state,String key,int day){JSONObject o=copy(state);try{JSONArray a=arr(o,"treaties");for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x!=null&&key.equals(x.optString("key")))x.put("consequence_pending",false).put("reviewed_day",Math.max(1,day));}o.put("treaties",a);}catch(Exception ignored){}return o;}
 public static JSONArray expiring(JSONObject state,int day){JSONArray z=new JSONArray(),a=arr(state,"treaties");for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x!=null&&"active".equals(x.optString("status"))&&x.optInt("expires_day",Integer.MAX_VALUE)<=day)z.put(x);}return z;}
 private static void addUnique(JSONObject o,String k,JSONObject x)throws Exception{JSONArray a=arr(o,k);for(int i=0;i<a.length();i++)if(x.optString("key").equals(a.optJSONObject(i)==null?"":a.optJSONObject(i).optString("key")))return;a.put(x);o.put(k,a);}private static JSONObject copy(JSONObject o){try{return o==null?new JSONObject():new JSONObject(o.toString());}catch(Exception e){return new JSONObject();}}private static JSONObject obj(JSONObject o,String k){JSONObject x=o==null?null:o.optJSONObject(k);return x==null?new JSONObject():x;}private static JSONArray arr(JSONObject o,String k){JSONArray x=o==null?null:o.optJSONArray(k);return x==null?new JSONArray():x;}
}
